SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3, triples t4, triples t5, triples t6, triples t7 WHERE t0.p = 'http://schema.org/caption' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://schema.org/text' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://schema.org/contentRating' AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://purl.org/stuff/rev#hasReview' AND struct_pack(kind := 0::UTINYINT, value := t4.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t3.o AND t4.p = 'http://purl.org/stuff/rev#title' AND struct_pack(kind := 0::UTINYINT, value := t5.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t3.o AND t5.p = 'http://purl.org/stuff/rev#reviewer' AND t6.p = 'http://schema.org/actor' AND t6.o = t5.o AND struct_pack(kind := 0::UTINYINT, value := t7.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t6.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t7.p = 'http://schema.org/language'